"""Write sources.bzl from protobuf's src/file_lists.cmake.

file_lists.cmake is generated upstream from the Bazel build and names the
files of each library the CMake build makes, as `set(<name>_srcs ...)` lists
of paths under ${protobuf_SOURCE_DIR}. This keeps the sources of the
libraries BUILD compiles, by the name of each list.

Usage:
    sources.py SRCDIR > sources.bzl
"""

import os
import re
import sys

LISTS = [
    "libprotobuf_srcs",
    "libprotoc_srcs",
    "libupb_srcs",
]

PREFIX = "${protobuf_SOURCE_DIR}/"


def main():
    srcdir = sys.argv[1]
    with open(os.path.join(srcdir, "src", "file_lists.cmake")) as f:
        text = f.read()

    out = sys.stdout
    out.write("# SPDX-FileCopyrightText: © 2024-2026 Austin Seipp\n")
    out.write("# SPDX-License-Identifier: Apache-2.0\n\n")
    out.write("# @generated by sources.py from src/file_lists.cmake. Do not edit; see\n")
    out.write("# sources-up-to-date in BUILD.\n\n")
    out.write("SOURCES = {\n")
    for name in LISTS:
        blocks = re.findall(r"^set\({}\n(.*?)^\)".format(re.escape(name)), text, re.S | re.M)
        if len(blocks) != 1:
            sys.exit("expected one set({}) in file_lists.cmake, found {}".format(name, len(blocks)))
        files = []
        for entry in blocks[0].split():
            if not entry.startswith(PREFIX):
                sys.exit("{}: {} is not under {}".format(name, entry, PREFIX))
            path = entry[len(PREFIX):]
            if not os.path.isfile(os.path.join(srcdir, path)):
                sys.exit("{} names {}, which is not in the source tree".format(name, path))
            files.append(path)
        out.write('    "{}": [\n'.format(name.removesuffix("_srcs")))
        for path in sorted(set(files)):
            out.write('        "{}",\n'.format(path))
        out.write("    ],\n")
    out.write("}\n")


if __name__ == "__main__":
    main()
